class RouterVerdictTests(unittest.TestCase):
    def test_the_one_node_decline_is_a_failure_not_a_pass(self):
        self.assertIn("EXITING router_sso test",
                      failure_markers_present(REAL_ONE_NODE_DECLINE))
        report = verdict(REAL_ONE_NODE_DECLINE, reached=True)
        self.assertEqual(report["verdict"], "FAIL")
        self.assertIn("missing two nodes discovered", report["problems"])

    def test_the_two_chassis_wedge_is_named(self):
        self.assertIn("Headless HUB inaccessible",
                      failure_markers_present(REAL_TWO_CHASSIS_WEDGE))
        report = verdict(REAL_TWO_CHASSIS_WEDGE, reached=False)
        self.assertEqual(report["verdict"], "FAIL")
        self.assertIn("missing MDK 1.6 banner", report["problems"])


if __name__ == "__main__":
    unittest.main()
